import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.BXzK3EA4.js";const o="/package_splitting.png",g=JSON.parse('{"title":"Day 11: Package Splitting & Installed-vs-Shipped","description":"","frontmatter":{},"headers":[],"relativePath":"day11-package-splitting-and-installed-vs-shipped.md","filePath":"day11-package-splitting-and-installed-vs-shipped.md"}'),l={name:"day11-package-splitting-and-installed-vs-shipped.md"};function d(n,e,p,h,r,c){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="day-11-package-splitting-installed-vs-shipped" tabindex="-1">Day 11: Package Splitting &amp; Installed-vs-Shipped <a class="header-anchor" href="#day-11-package-splitting-installed-vs-shipped" aria-label="Permalink to &quot;Day 11: Package Splitting &amp; Installed-vs-Shipped&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Explain the <code>do_package</code> task and the concept of Yocto package splitting</li><li>Control which files go into which packages using the <code>FILES:${PN}</code> variable</li><li>Troubleshoot the dreaded <code>installed-vs-shipped</code> QA error</li><li>Inspect the generated RPM/IPK packages to verify their contents</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day10-git-repositories-and-source-patching.html">Day 10: Git Repositories &amp; Source Patching</a></li></ul></div><hr><h2 id="_1-how-yocto-splits-packages" tabindex="-1">1. How Yocto Splits Packages <a class="header-anchor" href="#_1-how-yocto-splits-packages" aria-label="Permalink to &quot;1. How Yocto Splits Packages&quot;">​</a></h2><p>During the <code>do_install</code> task, a recipe installs <em>everything</em> (binaries, configuration files, man pages, C header files, static libraries, debug symbols) into the <code>${D}</code> (Destination) staging directory.</p><p>However, in an embedded system, disk space is at a premium. You don&#39;t want to install megabytes of C header files (<code>.h</code>) and debug symbols (<code>.debug</code>) onto the final production board.</p><p>To solve this, Yocto executes the <strong><code>do_package</code></strong> task. This task takes everything in <code>${D}</code> and splits it into granular, deployable packages (usually in <code>.rpm</code> or <code>.ipk</code> format) based on a set of rules.</p><p><img src="'+o+'" alt="Yocto Package Splitting Flow"></p><h3 id="the-default-packages-variable" tabindex="-1">The Default <code>PACKAGES</code> Variable <a class="header-anchor" href="#the-default-packages-variable" aria-label="Permalink to &quot;The Default `PACKAGES` Variable&quot;">​</a></h3><p>By default, Yocto attempts to split the output into the following packages (defined by the <code>PACKAGES</code> variable):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PACKAGES</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}-dbg ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}-staticdev ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}-dev ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}-doc ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}-locale ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span></code></pre></div><p><em>(Note: <code>${PN}</code> stands for Package Name, e.g., <code>helloworld</code>)</em></p><table tabindex="0"><thead><tr><th>Package</th><th>Purpose</th><th>Typical Contents</th></tr></thead><tbody><tr><td><code>${PN}-dbg</code></td><td>Debugging symbols</td><td><code>.debug/</code> directories, unstripped binaries</td></tr><tr><td><code>${PN}-dev</code></td><td>Development files</td><td><code>.h</code> headers, <code>.so</code> symlinks, <code>.pc</code> pkg-config files</td></tr><tr><td><code>${PN}-staticdev</code></td><td>Static libraries</td><td><code>.a</code> files</td></tr><tr><td><code>${PN}-doc</code></td><td>Documentation</td><td><code>/usr/share/man</code>, <code>/usr/share/doc</code></td></tr><tr><td><code>${PN}</code></td><td>The main binary package</td><td><code>/usr/bin/</code>, <code>/etc/</code>, <code>.so.1</code> libraries</td></tr></tbody></table><hr><h2 id="_2-controlling-the-split-files-pn" tabindex="-1">2. Controlling the Split: <code>FILES:${PN}</code> <a class="header-anchor" href="#_2-controlling-the-split-files-pn" aria-label="Permalink to &quot;2. Controlling the Split: `FILES:${PN}`&quot;">​</a></h2><p>How does <code>do_package</code> know which file goes where? It looks at the <code>FILES</code> variable for each package.</p><p>Yocto has sensible defaults. For example, it automatically knows that anything ending in <code>.h</code> goes into <code>${PN}-dev</code>. Anything in <code>/usr/bin</code> goes into the main <code>${PN}</code> package.</p><p>But what if you install a custom configuration file into a non-standard path?</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">do_install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ${D}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/mycompany/</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0644</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> custom.conf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ${D}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/mycompany/</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Because <code>/opt/mycompany/custom.conf</code> doesn&#39;t match any default Yocto rules, it will get left behind. You must explicitly tell Yocto which package should claim it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add the custom path to the main package&#39;s file list</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">FILES:$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">{PN}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/opt/mycompany/custom.conf&quot;</span></span></code></pre></div><hr><h2 id="_3-the-installed-vs-shipped-error" tabindex="-1">3. The <code>installed-vs-shipped</code> Error <a class="header-anchor" href="#_3-the-installed-vs-shipped-error" aria-label="Permalink to &quot;3. The `installed-vs-shipped` Error&quot;">​</a></h2><p>If you install a file into <code>${D}</code> during <code>do_install</code>, but <em>no</em> package claims it in their <code>FILES</code> variable, Yocto will halt the build with a <strong>QA Issue</strong>.</p><h3 id="example-error-output" tabindex="-1">Example Error Output <a class="header-anchor" href="#example-error-output" aria-label="Permalink to &quot;Example Error Output&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ERROR: helloworld-1.0-r0 do_package: QA Issue: helloworld: </span></span>\n<span class="line"><span>Files/directories were installed but not shipped in any package:</span></span>\n<span class="line"><span>  /opt/mycompany/custom.conf</span></span>\n<span class="line"><span>Please set FILES such that these items are packaged. Alternatively if they are unneeded, avoid installing them or delete them within do_install. [installed-vs-shipped]</span></span></code></pre></div><h3 id="how-to-fix-it" tabindex="-1">How to Fix It <a class="header-anchor" href="#how-to-fix-it" aria-label="Permalink to &quot;How to Fix It&quot;">​</a></h3><p>You have two choices:</p><ol><li><strong>Ship it:</strong> Add the path to <code>FILES:${PN} += &quot;/opt/...&quot;&quot;</code> as shown above.</li><li><strong>Don&#39;t install it:</strong> If it&#39;s a useless file generated by a third-party Makefile, delete it at the end of <code>do_install</code>:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">do_install:append</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ${D}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/mycompany/useless_file.txt</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h2 id="_4-hands-on-lab-exercises" tabindex="-1">4. Hands-On Lab Exercises <a class="header-anchor" href="#_4-hands-on-lab-exercises" aria-label="Permalink to &quot;4. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 11.1: Triggering the Error</p><ol><li>Open your <code>helloworld_1.0.bb</code> recipe.</li><li>Modify <code>do_install</code> to create a dummy file in a non-standard path:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ${D}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/test</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ${D}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/test/dummy.txt</span></span></code></pre></div></li><li>Rebuild the recipe: <code>bitbake helloworld</code>.</li><li>Observe the red <code>[installed-vs-shipped]</code> QA error in the console.</li><li>Fix the error by adding <code>FILES:${PN} += &quot;/opt/test/dummy.txt&quot;</code> and rebuilding.</li></ol></div><div class="tip custom-block"><p class="custom-block-title">LAB 11.2: Inspecting the Generated Packages</p><p>Let&#39;s look at the actual <code>.ipk</code> or <code>.rpm</code> files generated by the split.</p><ol><li>Navigate to <code>build/tmp/deploy/rpm/cortexa8.../</code> (or <code>ipk/</code>).</li><li>You will see <code>helloworld-1.0-r0.cortexa8.rpm</code> and <code>helloworld-dbg-1.0-r0.cortexa8.rpm</code>.</li><li>You can list the contents of the main package without installing it: <ul><li>For RPM: <code>rpm -qlp helloworld-1.0-r0...rpm</code></li><li>For IPK: <code>ar p helloworld-1.0...ipk data.tar.gz | tar zt</code></li></ul></li><li>Verify your <code>/opt/test/dummy.txt</code> file is inside the main package!</li></ol></div><hr><h2 id="_5-further-reading" tabindex="-1">5. Further Reading <a class="header-anchor" href="#_5-further-reading" aria-label="Permalink to &quot;5. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Package Splitting Mechanics</td><td><a href="https://docs.yoctoproject.org/dev-manual/packages.html" target="_blank" rel="noreferrer">docs.yoctoproject.org/dev-manual/packages.html</a></td></tr><tr><td>QA Error Reference</td><td><a href="https://docs.yoctoproject.org/ref-manual/qa-checks.html#qa-issue-installed-vs-shipped" target="_blank" rel="noreferrer">docs.yoctoproject.org/ref-manual/qa-checks.html#qa-issue-installed-vs-shipped</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day10-git-repositories-and-source-patching">← Day 10: Git Repos &amp; Patching</a><a href="/day12-static-and-dynamic-shared-libraries">Day 12: Static &amp; Dynamic Libraries →</a></div>',40)])])}const u=a(l,[["render",d]]);export{g as __pageData,u as default};
